#!/usr/bin/env python3
"""Records-retention sweeper with a dry-run mode.

Given a root directory and a YAML schedule mapping glob patterns to maximum
file ages (in days), files older than their pattern's limit are deleted.
The most-specific (longest) matching pattern wins. Everything under any
directory containing a file named LEGAL_HOLD is exempt and reported as held.

Default behaviour is a dry run that only prints what would happen;
pass --apply to actually delete.
"""

from __future__ import annotations

import argparse
import fnmatch
import os
import sys
import time
from pathlib import Path

import yaml

HOLD_MARKER = "LEGAL_HOLD"
SECONDS_PER_DAY = 86400

# Table layout shared with the test-suite so the exact report can be asserted.
ACTION_W = 13
AGE_W = 9
PATTERN_W = 15


def load_schedule(path: str | Path) -> dict[str, int]:
    """Load {glob pattern: max age in days} from a YAML file."""
    with open(path, encoding="utf-8") as fh:
        data = yaml.safe_load(fh)
    if not isinstance(data, dict):
        raise SystemExit(f"schedule {path!r} must be a mapping of pattern -> days")
    for pattern, days in data.items():
        if not isinstance(pattern, str) or not isinstance(days, int):
            raise SystemExit(
                f"schedule {path!r}: entries must map string patterns to integer days "
                f"(got {pattern!r} -> {days!r})"
            )
    return data


def find_hold_dirs(root: Path) -> set[Path]:
    """Return every directory under *root* containing a LEGAL_HOLD marker."""
    holds: set[Path] = set()
    for dirpath, _dirnames, filenames in os.walk(root):
        if HOLD_MARKER in filenames:
            holds.add(Path(dirpath))
    return holds


def is_held(path: Path, hold_dirs: set[Path]) -> bool:
    return any(hold == path or hold in path.parents for hold in hold_dirs)


def best_pattern(rel: str, schedule: dict[str, int]) -> str | None:
    """Longest glob pattern in *schedule* matching *rel*, or None."""
    matches = [p for p in schedule if fnmatch.fnmatch(rel, p)]
    if not matches:
        return None
    return max(matches, key=len)


class Row:
    __slots__ = ("action", "age_days", "pattern", "rel")

    def __init__(self, action: str, age_days: float, pattern: str, rel: str):
        self.action = action  # "delete" | "held" | "keep"
        self.age_days = age_days
        self.pattern = pattern
        self.rel = rel


def classify(root: Path, schedule: dict[str, int], now: float | None = None) -> list[Row]:
    now = time.time() if now is None else now
    hold_dirs = find_hold_dirs(root)
    rows: list[Row] = []
    for dirpath, _dirnames, filenames in os.walk(root):
        for name in filenames:
            if name == HOLD_MARKER:
                continue
            full = Path(dirpath) / name
            rel = full.relative_to(root).as_posix()
            pattern = best_pattern(rel, schedule)
            if pattern is None:
                continue  # not covered by any retention family
            age_days = (now - full.stat().st_mtime) / SECONDS_PER_DAY
            if is_held(full, hold_dirs):
                action = "held"
            elif age_days > schedule[pattern]:
                action = "delete"
            else:
                action = "keep"
            rows.append(Row(action, age_days, pattern, rel))
    rows.sort(key=lambda r: r.rel)
    return rows


def format_header() -> str:
    return (
        f"{'ACTION':<{ACTION_W}}{'AGE_DAYS':>{AGE_W}}  "
        f"{'PATTERN':<{PATTERN_W}} PATH"
    )


def format_row(action_label: str, age_days: float, pattern: str, rel: str) -> str:
    return (
        f"{action_label:<{ACTION_W}}{age_days:>{AGE_W}.1f}  "
        f"{pattern:<{PATTERN_W}} {rel}"
    )


def render(rows: list[Row], apply: bool) -> str:
    lines = [format_header()]
    for row in rows:
        label = {"delete": "deleted" if apply else "would-delete",
                 "held": "held", "keep": "kept"}[row.action]
        lines.append(format_row(label, row.age_days, row.pattern, row.rel))
    return "\n".join(lines)


def main(argv: list[str] | None = None) -> int:
    parser = argparse.ArgumentParser(description="Records-retention sweeper.")
    parser.add_argument("root", help="directory to sweep")
    parser.add_argument("-s", "--schedule", default="schedule.yaml",
                        help="YAML schedule of glob pattern -> max age in days")
    parser.add_argument("--apply", action="store_true",
                        help="actually delete expired files (default: dry-run)")
    args = parser.parse_args(argv)

    root = Path(args.root)
    if not root.is_dir():
        parser.error(f"root {str(root)!r} is not a directory")

    schedule = load_schedule(args.schedule)
    rows = classify(root, schedule)

    print(render(rows, apply=args.apply))

    if args.apply:
        for row in rows:
            if row.action == "delete":
                (root / row.rel).unlink()

    return 0


if __name__ == "__main__":
    sys.exit(main())

