"""Tests for the records-retention sweeper."""

import os
import time
from pathlib import Path

import pytest

import sweep

DAY = sweep.SECONDS_PER_DAY

# rel path -> age in days for the fixture tree
FIXTURE_FILES = {
    # logs family: limit 30 days
    "logs/recent.log": 5,
    "logs/stale.log": 40,
    "logs/deep/nested/ancient.log": 4000,
    # exports family: limit 7 days
    "exports/fresh.csv": 5,
    "exports/expired.csv": 40,
    # archive family: limit 3650 days
    "archive/keeper.zip": 5,
    "archive/mid.zip": 40,
    "archive/tarball.tar": 4000,
    # held directory: over-age but exempt via LEGAL_HOLD marker
    "project/held/held-data.csv": 40,
    "project/held/logs/held-old.log": 4000,
}

HELD_DIR = "project/held"

# (rel, action, pattern) in the order the report renders them (sorted by rel).
EXPECTED_ROWS = [
    ("kept", "archive/keeper.zip", "archive/**"),
    ("kept", "archive/mid.zip", "archive/**"),
    ("would-delete", "archive/tarball.tar", "archive/**"),
    ("would-delete", "exports/expired.csv", "exports/**.csv"),
    ("kept", "exports/fresh.csv", "exports/**.csv"),
    ("would-delete", "logs/deep/nested/ancient.log", "logs/**.log"),
    ("kept", "logs/recent.log", "logs/**.log"),
    ("would-delete", "logs/stale.log", "logs/**.log"),
    ("held", "project/held/held-data.csv", "exports/**.csv"),
    ("held", "project/held/logs/held-old.log", "logs/**.log"),
]


def make_tree(root: Path) -> Path:
    """Build the fixture tree with mtimes set via os.utime."""
    root.mkdir(parents=True)
    now = time.time()
    for rel, age_days in FIXTURE_FILES.items():
        path = root / rel
        path.parent.mkdir(parents=True, exist_ok=True)
        path.write_text(f"contents of {rel}\n")
        os.utime(path, (now - age_days * DAY, now - age_days * DAY))
    hold_marker = root / HELD_DIR / sweep.HOLD_MARKER
    hold_marker.write_text("litigation hold\n")
    os.utime(hold_marker, (now, now))
    return root


@pytest.fixture
def tree(tmp_path: Path) -> Path:
    return make_tree(tmp_path / "data")


def snapshot(root: Path) -> set[str]:
    return {
        p.relative_to(root).as_posix()
        for p in root.rglob("*")
        if p.is_file()
    }


def expected_report(label_map: dict[str, str]) -> str:
    lines = [sweep.format_header()]
    ages = {rel: float(age) for rel, age in FIXTURE_FILES.items()}
    for label, rel, pattern in EXPECTED_ROWS:
        lines.append(
            sweep.format_row(label_map[label], ages[rel], pattern, rel)
        )
    return "\n".join(lines)


def test_dry_run_report_exact(tree, capsys):
    rc = sweep.main([str(tree), "-s", "schedule.yaml"])
    out = capsys.readouterr().out
    assert rc == 0
    assert out == expected_report(
        {"kept": "kept", "held": "held", "would-delete": "would-delete"}
    ) + "\n"


def test_dry_run_deletes_nothing(tree):
    before = snapshot(tree)
    sweep.main([str(tree), "-s", "schedule.yaml"])
    assert snapshot(tree) == before
    assert FIXTURE_FILES.keys() | {sweep.HOLD_MARKER} <= {
        rel.split("/", 1)[-1] and rel or rel for rel in before
    } or True  # snapshot completeness checked below
    for rel in FIXTURE_FILES:
        assert (tree / rel).exists()


def test_apply_removes_exactly_expected(tree, capsys):
    rc = sweep.main(["--apply", str(tree), "-s", "schedule.yaml"])
    assert rc == 0

    # The apply-mode table marks the expired rows as deleted.
    out = capsys.readouterr().out
    assert out == expected_report(
        {"kept": "kept", "held": "held", "would-delete": "deleted"}
    ) + "\n"

    remaining = snapshot(tree)
    expected_remaining = set(FIXTURE_FILES) | {sweep.HOLD_MARKER}
    for rel, age in FIXTURE_FILES.items():
        if age > {"logs/**.log": 30, "exports/**.csv": 7, "archive/**": 3650}[
            next(p for p in ["logs/**.log", "exports/**.csv", "archive/**"]
                 if rel.startswith(p.split("/")[0]))
        ]:
            expected_remaining.discard(rel)

    assert remaining == expected_remaining

    # Exactly these were removed:
    removed = {
        "archive/tarball.tar",
        "exports/expired.csv",
        "logs/deep/nested/ancient.log",
        "logs/stale.log",
    }
    for rel in removed:
        assert not (tree / rel).exists()


def test_held_files_survive_apply(tree):
    sweep.main(["--apply", str(tree), "-s", "schedule.yaml"])
    assert (tree / HELD_DIR / sweep.HOLD_MARKER).exists()
    for rel, _age in FIXTURE_FILES.items():
        if rel.startswith(HELD_DIR + "/"):
            assert (tree / rel).exists(), f"held file was deleted: {rel}"


def test_longest_matching_pattern_wins(tmp_path):
    schedule = {"a/**": 10, "a/special/**.log": 100}
    assert sweep.best_pattern("a/x.txt", schedule) == "a/**"
    assert sweep.best_pattern("a/special/deep/x.log", schedule) == "a/special/**.log"
    assert sweep.best_pattern("b/x.txt", schedule) is None


def test_cli_dry_run_is_default_subprocess(tree):
    import subprocess
    import sys

    repo = Path(sweep.__file__).resolve().parent
    result = subprocess.run(
        [sys.executable, str(repo / "sweep.py"), str(tree),
         "-s", str(repo / "schedule.yaml")],
        capture_output=True, text=True, check=True,
    )
    assert result.stdout == expected_report(
        {"kept": "kept", "held": "held", "would-delete": "would-delete"}
    ) + "\n"
    # nothing deleted
    for rel in FIXTURE_FILES:
        assert (tree / rel).exists()

